SELECT COUNT(session_id), SUM(CASE WHEN added_to_cart THEN 1 ELSE 0 END), SUM(CASE WHEN converted_order_id IS NOT NULL THEN 1 ELSE 0 END) FROM web_sessions WHERE started_at_utc >= TIMESTAMP '2025-11-01 00:00:00' - INTERVAL 6 HOUR AND started_at_utc < TIMESTAMP '2025-11-30 00:00:00' + INTERVAL 18 HOUR
